{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "Many AI models inherit biases due to the underrepresentation of diverse populations in datasets and reliance on historically biased data. This leads to unfair and less inclusive outcomes. Aspects contributing to these weaknesses mentioned in the papers are lack of diverse data, over-reliance on datasets from high-income countries or bias in clinical care. Another weakness is the lack of standardized frameworks, ethical guidelines, and clear user consent processes.",
      "reason": "The discussion explicitly describes the current state of knowledge (AI promises but inherit biases, data limitations, lack of frameworks) and uncertainties/gaps (limited empirical evidence, predominance of expert opinion), meeting the requirement to describe current state and important uncertainties."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "In this study we prioritize the literature to explicitly addressing 'inclusive AI' in healthcare as this area has not been well addressed in prior studies.",
      "reason": "The methods and abstract state the need for the review (inclusive AI in healthcare has not been well addressed) and the review's aim to examine inclusive AI, explaining the importance and rationale for conducting the review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved evidence identifies existing similar systematic reviews or explains the need for the current review relative to prior reviews; no prior review is cited or discussed as an update or replication."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "This current study aims to examine inclusive AI in healthcare grounded on a patient-centered approach. Methods We conducted a literature review following PRISMA 2020 guidelines, searching across online databases for publications from diverse geographic and cultural contexts.",
      "reason": "The review is a literature/systematic review of inclusive AI rather than a review of intervention effects; therefore describing an intervention's mechanism of action does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_7",
      "quote": "In this study, a literature review was adopted as the chosen research approach by carrying out a systematic review with conceptual synthesis, following the PRISMA 2020 guidelines [21], as seen in Appendix 3.",
      "reason": "The review is not of a complex intervention or delivery context and no logic model is presented; thus the requirement to consider a logic model is not applicable."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "Our study was guided by the following research questions: ... What are the facets of inclusive AI, and what are the recommended strategies, solutions, and regulatory frameworks needed to realize inclusive AI technologies in healthcare? What are the application areas where inclusive AI technologies have been investigated? What are the potential benefits (strengths and benefits) of inclusive AI technologies within the healthcare domain? What are the potential challenges (weaknesses and threats) of inclusive AI technologies within the healthcare domain?",
      "reason": "The review explicitly states multiple research questions and objectives (supporting the requirement to provide objectives/questions). However, the questions are not presented using a formal question‑formulation framework (e.g., PICO, PICOS, or similar), so the criterion is only partially met."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is a literature/systematic review of inclusive AI in healthcare and does not assess intervention effects or planned comparisons; therefore PICO-style planned comparisons are not applicable."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "We searched six databases (PubMed, PsycINFO, CINAHL, Academic Search Premier, IEEE Xplore, and Scopus) for publications that included the keyword 'Inclusive AI' in their abstract. In this study we prioritize the literature to explicitly addressing 'inclusive AI' in healthcare as this area has not been well addressed in prior studies. Accordingly, we used only the keyword 'Inclusive AI' 'strategies', 'solutions', 'regulatory frameworks', 'applications', 'benefits', 'challenges', AND 'bias', 'fair - ness', 'equity', OR 'diversity' AND 'healthcare' to ensure the search captured publications where inclusivity was an explicit and central focus.",
      "reason": "The manuscript specifies databases searched and detailed search keywords and prioritization (i.e., scope targeted to 'inclusive AI' in healthcare), but it does not comprehensively list all study characteristics used to determine eligibility (for example, eligible study designs, settings, participant or follow-up requirements are not provided)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "All included articles were published between 2020 and 2024.",
      "reason": "The review reports the publication years of included articles. Additional report-characteristic restrictions are documented: text_20 notes language/databases limitation ('our search was limited to English-only databases') and text_6 lists excluded publication types (e.g., 'Publications for which only the abstract is available... Study protocols, reviews... Editorials, letters to editor... proceedings, books, etc.'), showing criteria on language, years, and publication/report status."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was found distinguishing exclusion because outcomes were not measured from exclusion because outcome results were not reported; the methods and exclusions describe general reasons and publication types but do not make this specific distinction."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": "text_7",
      "quote": "All selected articles were included in qualitative synthesis and were divided between two authors (EG and KD), with each author extracting data from half of the articles.",
      "reason": "While the manuscript states that all included articles were used in a qualitative synthesis and describes data extraction logistics, it does not specify groups used in each synthesis or link groups to comparisons defined in the review objectives (no explicit synthesis-group definitions or comparison mappings were reported)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "In this study we prioritize the literature to explicitly addressing 'inclusive AI' in healthcare as this area has not been well addressed in prior studies. Accordingly, we used only the keyword 'Inclusive AI' ... to ensure the search captured publications where inclusivity was an explicit and central focus.",
      "reason": "The authors provide a rationale for the notable restriction to literature explicitly addressing 'inclusive AI' (to focus on publications where inclusivity is an explicit central focus). Additionally, text_20 explains limitations regarding language and database scope, further justifying some eligibility restrictions."
    }
  ],
  "confidence": 75
}

